/* Help */
.help-panel { width: min(880px, 100%) !important; }
.help-body { display: grid; grid-template-columns: 1fr 1.1fr; gap: 28px; }
.help-body h3 { font-family: var(--font-head); font-size: 12px; letter-spacing: .2em; color: var(--amber); margin: 0 0 9px; }
.help-body h3:not(:first-child) { margin-top: 18px; }
.key-list { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 5px 14px; }
.key-list li { display: flex; align-items: center; gap: 8px; font-size: 10px; color: var(--muted); }
.key-list kbd { min-width: 52px; padding: 2px 6px; border: 1px solid rgba(255,255,255,.14); border-bottom-width: 2px; background: rgba(255,255,255,.04); font-family: var(--font-head); font-size: 10px; color: #e4dac4; text-align: center; }
.touch-note { font-size: 9.5px; color: var(--dim); line-height: 1.6; margin-top: 14px; border-left: 2px solid rgba(243,180,95,.2); padding-left: 10px; }
.help-steps { display: flex; flex-direction: column; gap: 8px; }
