.death-panel > p { color: var(--muted); font-size: 11px; line-height: 1.6; max-width: 380px; margin: 10px auto 0; }
.death-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin: 18px 0; }
