`updateSky()`:
```
const t=this.time;
let darkness=0;
if (t>0.44 && t<0.53) darkness = (t-0.44)/0.09 * 0.52;
else if (t>=0.53 && t<0.57) darkness=0.52+((t-0.53)/0.04)*0.16;
else if (t>=0.57 && t<0.95) darkness=0.68;
else if (t>=0.95) darkness=0.68*(1-(t-0.95)/0.05);
else if (t<0.05) darkness=0; // dawn
this.darkness=darkness;
