```js
const bullets = this.bullets;
for (let i=bullets.length-1;i>=0;i--){
 const b=bullets[i];
 b.px=b.x; b.py=b.y;
 const speed=Math.hypot(b.vx,b.vy);
 const steps=clamp(Math.ceil(speed*dt/14),1,8);
 let dead=false;
 for (let s=0;s<steps && !dead;s++){
   const nx=b.x+b.vx*dt/steps, ny=b.y+b.vy*dt/steps;
   // world solids
   for rect: if segmentRect(b.x,b.y,nx,ny,rect) → impact at approximate nx,ny, dead; break; sfx spark
   for circ:
      if ref.kind==='barrel' && ref.alive: if segmentCircle(...) → damageBarrel(ref,b.dmg); dead; explode? bullet impact triggers barrel damage.
      else if segmentCircle(...) → dead
   if dead break;
   // enemies for player/ally
   for e:
     if e.alive && segmentCircle(b.x,b.y,nx,ny,e.x,e.y,e.r + (b.radius||1)) {
        this.damageEnemy(e,b.dmg,{x:b.x,y:b.y}); 
        if(b.explosive) { this.explode(nx,ny,b.area,b.dmg,{source:'player'}); }
        dead=true; break;
     }
   b.x=nx;b.y=ny;
 }
 if (!dead) { b.life-=dt; if out of bounds/life<=0 dead }
 if (dead) { impact particles ... if explosive explode; bullets.splice }
}
