104:   bind() {
105:     document.addEventListener('click', (e) => {
106:       const target = e.target.closest('[data-action]');
107:       if (!target) return;
108:       e.preventDefault();
109:       e.stopPropagation();
110:       this.dispatch(target.dataset.action, target);
111:     });
112:     if (this.el.toggleSound) {
113:       this.el.toggleSound.addEventListener('change', () => this.game.setSound(this.el.toggleSound.checked));
114:     }
115:     if (this.el.toggleAssist) {
116:       this.el.toggleAssist.addEventListener('change', () => this.game.setAimAssist(this.el.toggleAssist.checked));
117:     }
118:     // Prevent clicks inside menus from reaching the canvas.
119:     for (const menu of [this.el.buildMenu, this.el.upgradeMenu, this.el.questMenu, this.el.pauseMenu, this.el.helpMenu, this.el.deathScreen]) {
120:       if (!menu) continue;
121:       menu.addEventListener('pointerdown', (e) => e.stopPropagation());
122:     }
123:   }
124: 
125:   setTouch(touch) {
126:     document.body.classList.toggle('touch', !!touch);
127:     if (this.el.titleControls) {
128:       this.el.titleControls.textContent = touch
129:         ? 'Cần trái di chuyển · Cần phải ngắm & bắn · Nút XÂY để dựng căn cứ · Chạm MỞ để nhặt đồ'
130:         : 'WASD di chuyển · Chuột ngắm & bắn · B xây dựng · E nhặt đồ · J nhiệm vụ';
131:     }
132:   }
133: 
134:   syncSettings() {
135:     const s = this.game.settings;
136:     if (this.el.toggleSound) this.el.toggleSound.checked = !!s.sound;
137:     if (this.el.toggleAssist) this.el.toggleAssist.checked = !!s.aimAssist;
138:     if (this.el.soundBtn) this.el.soundBtn.classList.toggle('off', !s.sound);
139:   }
140: 
141:   dispatch(action, el) {
142:     const g = this.game;
143:     switch (action) {
144:       case 'start-new': g.startNew(); break;
145:       case 'continue': g.continueRun(); break;
146:       case 'help': g.openHelp(); break;
147:       case 'close-help': g.closeHelp(); break;
148:       case 'pause': g.togglePause(); break;
149:       case 'resume': g.resume(); break;
150:       case 'quests': g.openQuests(); break;
151:       case 'close-menu': g.closeMenu(); break;
152:       case 'build': g.toggleBuild(); break;
153:       case 'build-close': g.closeBuild(); break;
154:       case 'build-place': g.placeBuild(); break;
155:       case 'build-select': g.selectBuild(el.dataset.build); break;
156:       case 'recruit': g.recruitSoldier(); break;
157:       case 'core-upgrade': g.upgradeCore(); break;
158:       case 'buy-medkit': g.buyMedkit(); break;
159:       case 'weapon-upgrade': g.upgradeWeapon(el.dataset.weapon); break;
160:       case 'respawn': g.respawn(); break;
161:       case 'restart-run': g.restartRun(); break;
162:       case 'quit-title': g.quitToTitle(); break;
163:       case 'wipe-save': g.wipeSave(); break;
164:       case 'sound': g.toggleSound(); this.syncSettings(); break;
165:       case 'open-upgrade': g.openUpgradeFromPause(); break;
166:       case 'reload': if (g.player.alive) g.player.reload(g); break;
167:       case 'heal': if (g.player.alive) g.player.useMedkit(g); break;
168:       case 'melee': if (g.player.alive && g.canAct()) g.player.quickMelee(g); break;
169:       case 'interact': g.interact(); break;
170:       case 'cycle': if (g.player.alive) g.player.cycleWeapon(1, g); break;
171:       default: break;
172:     }
173:   }
