325:   rewardMarkup(reward) {
326:     const bits = [];
327:     if (reward.scrap) bits.push(`<b>+${Math.round(reward.scrap)} sắt</b>`);
328:     if (reward.parts) bits.push(`<b>+${Math.round(reward.parts)} linh kiện</b>`);
329:     if (reward.wood) bits.push(`<em>+${Math.round(reward.wood)} gỗ</em>`);
330:     if (reward.medkit) bits.push(`<b>+${reward.medkit} sơ cứu</b>`);
331:     if (reward.xp) bits.push(`<em>+${Math.round(reward.xp)} XP</em>`);
332:     return bits.slice(0, 3).join('');
