342:   renderBuild(game, force = false) {
343:     const sig = this.buildSignature(game);
344:     if (!force && sig === this.lastBuildSig) return;
345:     this.lastBuildSig = sig;
346:     const cards = Object.values(BUILDS).map((b) => {
347:       const count = game.structureCount(b.id);
348:       const limit = game.structureLimit(b.id);
349:       const afford = game.canAfford(b.cost);
350:       const selected = game.buildKind === b.id;
351:       const costs = this.costChips(b.cost, game);
352:       return `<button class="build-card ${selected ? 'selected' : ''} ${afford ? '' : 'unaffordable'}" data-action="build-select" data-build="${b.id}">
353:         <div class="bc-icon">${SVG[b.icon] || ''}</div>
354:         <div class="bc-body">
355:           <div class="bc-name"><b>${b.name}</b><span>${b.hp} HP</span></div>
356:           <div class="bc-desc">${b.desc}</div>
357:           <div class="bc-cost">${costs}</div>
358:         </div>
359:         <div class="bc-side">
360:           <span class="bc-count"><b>${count}</b> / ${limit}</span>
361:           <span class="bc-select">${selected ? 'ĐANG CHỌN' : 'CHỌN'}</span>
362:         </div>
363:       </button>`;
364:     }).join('');
365:     this.el.buildGrid.innerHTML = cards;
