367:     const maxSoldiers = game.maxSoldiers();
368:     const recruitCost = this.costChips(RECRUIT_COST, game);
369:     const coreNext = CORE_UPGRADES[game.core.level] || null;
370:     const coreCost = coreNext ? this.costChips(coreNext.cost, game) : '';
371:     this.el.baseActions.innerHTML = `
372:       <div class="base-card">
373:         <h4>CHIÊU MỘ LÍNH</h4>
