381:         <div class="bc-cost">${coreNext ? coreCost : '<span class="cost-chip good">TỐI ĐA</span>'}</div>
382:         <button class="btn tiny" data-action="core-upgrade">${coreNext ? 'NÂNG CẤP LÕI' : 'ĐÃ TỐI ĐA'}</button>
383:       </div>
384:       <div class="base-card">
385:         <h4>BỘ SƠ CỨU</h4>
386:         <p>Hồi 45 máu khi sử dụng. Bạn đang có ${game.player.medkits}.</p>
387:         <div class="bc-cost">${this.costChips(HEAL_KIT_PRICE, game)}</div>
388:         <button class="btn tiny" data-action="buy-medkit">MUA · 15 SẮT</button>
