464:   refreshHotbar(game) {
465:     const order = game.player.weaponOrder.filter((id) => game.player.unlocked.has(id));
466:     const sig = order.join(',');
467:     if (sig !== this.hotbarSig) {
468:       this.hotbarSig = sig;
469:       this.el.hotbar.innerHTML = order.map((id, i) => {
470:         const def = WEAPONS[id];
471:         return `<div class="slot" data-weapon="${id}">
472:           <span class="slot-key">${i + 1}</span>
473:           <div class="slot-top"><span class="slot-icon">${SVG[def.icon] || ''}</span><span class="slot-name">${def.name}</span></div>
474:           <span class="slot-ammo" data-ammo="${id}"></span>
475:         </div>`;
476:       }).join('');
477:     }
478:     for (const id of order) {
479:       const slot = this.el.hotbar.querySelector(`.slot[data-weapon="${id}"]`);
480:       if (!slot) continue;
481:       slot.classList.toggle('active', game.player.current === id);
482:       const w = game.player.weapons[id];
483:       const st = game.player.weaponStats(game, id);
484:       const ammo = slot.querySelector('[data-ammo]');
485:       if (st.kind === 'melee') {
486:         ammo.innerHTML = '∞ <em>CẬN CHIẾN</em>';
