1659:       if (!s.alive) continue;
1660:       let radius = 0;
1661:       if (s.kind === 'lampbuild') radius = 230;
1662:       else if (s.kind === 'medbay') radius = 120;
1663:       else if (s.kind === 'turret') radius = 70;
1664:       if (radius) this.lightHole(lctx, this.worldToScreenX(s.x), this.worldToScreenY(s.y), radius, s.kind === 'lampbuild' ? 0.9 : 0.5);
1665:     }
1666:     for (const l of g.world.lamps) {
1667:       this.lightHole(lctx, this.worldToScreenX(l.x), this.worldToScreenY(l.y), 170, g.isNight ? 0.85 : 0.5);
1668:     }
1669:     for (const p of g.particles) {
1670:       if (p.type === 'muzzle' || p.type === 'ring') {
1671:         this.lightHole(lctx, this.worldToScreenX(p.x), this.worldToScreenY(p.y), 100 * (p.life / p.maxLife), 0.6);
1672:       }
1673:     }
1674:     lctx.globalCompositeOperation = 'source-over';
1675:     const ctx = this.ctx;
1676:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
1677:     ctx.drawImage(lc, 0, 0, w, h);
1678:   }
