1680:   lightHole(ctx, x, y, radius, strength) {
1681:     if (radius <= 1) return;
1682:     const grd = ctx.createRadialGradient(x, y, 0, x, y, radius);
1683:     grd.addColorStop(0, `rgba(0,0,0,${strength})`);
1684:     grd.addColorStop(0.55, `rgba(0,0,0,${strength * 0.6})`);
1685:     grd.addColorStop(1, 'rgba(0,0,0,0)');
1686:     ctx.fillStyle = grd;
1687:     ctx.beginPath();
1688:     ctx.arc(x, y, radius, 0, TAU);
1689:     ctx.fill();
1690:   }
