1700:   drawNightGlows(g, time) {
1701:     const ctx = this.ctx;
1702:     const w = this.w;
1703:     const h = this.h;
1704:     if (g.darkness < 0.05) return;
1705:     ctx.save();
1706:     ctx.globalCompositeOperation = 'lighter';
1707:     const fire = g.world.base.fire;
1708:     const fx = this.worldToScreenX(fire.x);
1709:     const fy = this.worldToScreenY(fire.y);
1710:     const glow = ctx.createRadialGradient(fx, fy, 4, fx, fy, 240);
1711:     glow.addColorStop(0, 'rgba(255,148,56,0.16)');
1712:     glow.addColorStop(1, 'rgba(255,100,20,0)');
1713:     ctx.fillStyle = glow;
1714:     ctx.beginPath();
1715:     ctx.arc(fx, fy, 240, 0, TAU);
1716:     ctx.fill();
1717:     for (const l of g.world.lamps) {
1718:       if (!g.isNight) continue;
1719:       const x = this.worldToScreenX(l.x);
1720:       const y = this.worldToScreenY(l.y);
1721:       if (x < -80 || x > w + 80 || y < -80 || y > h + 80) continue;
1722:       const lg = ctx.createRadialGradient(x, y - 20 * this.zoom, 2, x, y - 20 * this.zoom, 120 * this.zoom);
1723:       lg.addColorStop(0, 'rgba(255,200,110,0.12)');
1724:       lg.addColorStop(1, 'rgba(255,180,80,0)');
1725:       ctx.fillStyle = lg;
1726:       ctx.beginPath();
1727:       ctx.arc(x, y - 20 * this.zoom, 120 * this.zoom, 0, TAU);
1728:       ctx.fill();
1729:     }
1730:     // enemy eyes
1731:     if (g.isNight) {
1732:       for (const e of g.enemies) {
1733:         if (!e.alive) continue;
1734:         const x = this.worldToScreenX(e.x);
1735:         const y = this.worldToScreenY(e.y);
1736:         if (x < -40 || x > w + 40 || y < -40 || y > h + 40) continue;
1737:         const a = Math.atan2(e.angle);
1738:         const off = e.r * 0.55 * this.zoom;
1739:         const alpha = 0.5 + Math.sin(time * 3 + e.x) * 0.18;
1740:         ctx.fillStyle = e.boss ? `rgba(255,60,50,${alpha})` : `rgba(255,196,90,${alpha})`;
1741:         ctx.beginPath();
1742:         ctx.arc(x + Math.cos(a) * off + Math.sin(a) * 4 * this.zoom, y + Math.sin(a) * off - Math.cos(a) * 4 * this.zoom, (e.boss ? 3 : 1.7) * this.zoom, 0, TAU);
1743:         ctx.fill();
1744:         ctx.beginPath();
1745:         ctx.arc(x + Math.cos(a) * off - Math.sin(a) * 4 * this.zoom, y + Math.sin(a) * off + Math.cos(a) * 4 * this.zoom, (e.boss ? 3 : 1.7) * this.zoom, 0, TAU);
1746:         ctx.fill();
1747:         if (e.boss) {
1748:           const bg = ctx.createRadialGradient(x, y, 10, x, y, 90 * this.zoom);
1749:           bg.addColorStop(0, 'rgba(255,40,30,0.08)');
1750:           bg.addColorStop(1, 'rgba(255,40,30,0)');
1751:           ctx.fillStyle = bg;
1752:           ctx.beginPath();
1753:           ctx.arc(x, y, 90 * this.zoom, 0, TAU);
1754:           ctx.fill();
1755:         }
1756:       }
1757:     }
1758:     // supply beacon
1759:     if (g.supplyDrop) {
1760:       const s = g.supplyDrop;
1761:       const x = this.worldToScreenX(s.x);
1762:       const y = this.worldToScreenY(s.y);
1763:       const bg = ctx.createLinearGradient(x, y - 400, x, y);
1764:       bg.addColorStop(0, 'rgba(150,255,110,0)');
1765:       bg.addColorStop(1, 'rgba(150,255,110,0.16)');
1766:       ctx.fillStyle = bg;
1767:       ctx.fillRect(x - 16, y - 400, 32, 400);
1768:     }
1769:     ctx.restore();
1770:   }
1771: 
1772:   drawScreenFx(g, time) {
1773:     const ctx = this.ctx;
1774:     const w = this.w;
1775:     const h = this.h;
1776:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
1777:     // vignette
1778:     const grd = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.3, w / 2, h / 2, Math.max(w, h) * 0.75);
1779:     grd.addColorStop(0, 'rgba(0,0,0,0)');
1780:     grd.addColorStop(1, 'rgba(0,0,0,0.6)');
1781:     ctx.fillStyle = grd;
1782:     ctx.fillRect(0, 0, w, h);
1783:     // damage vignette
1784:     if (g.hitFlash > 0) {
1785:       const red = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.25, w / 2, h / 2, Math.max(w, h) * 0.72);
1786:       red.addColorStop(0, 'rgba(120,10,10,0)');
1787:       red.addColorStop(1, `rgba(150,15,12,${0.45 * g.hitFlash})`);
1788:       ctx.fillStyle = red;
1789:       ctx.fillRect(0, 0, w, h);
1790:     }
1791:     // low health pulse
1792:     if (g.player.alive && g.player.hp / g.player.maxHp < 0.3) {
1793:       const a = 0.1 + Math.sin(time * 6) * 0.05;
1794:       const red = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.3, w / 2, h / 2, Math.max(w, h) * 0.7);
1795:       red.addColorStop(0, 'rgba(90,8,8,0)');
1796:       red.addColorStop(1, `rgba(120,10,10,${a})`);
1797:       ctx.fillStyle = red;
1798:       ctx.fillRect(0, 0, w, h);
1799:     }
1800:     // dusk grading
1801:     if (g.phase === 'dusk') {
1802:       ctx.fillStyle = 'rgba(150,70,25,0.06)';
1803:       ctx.fillRect(0, 0, w, h);
1804:     }
1805:   }
