1807:   drawReticle(g) {
1808:     if (g.touch || g.buildMode || g.menuOpen || g.mode !== 'playing') return;
1809:     const ctx = this.ctx;
1810:     const p = g.screenToWorld(g.input.mouse.x, g.input.mouse.y);
1811:     const x = this.worldToScreenX(p.x);
1812:     const y = this.worldToScreenY(p.y);
1813:     const target = g.enemyAt(p.x, p.y, 30);
1814:     const col = target ? 'rgba(255,105,80,0.95)' : 'rgba(255,210,140,0.9)';
1815:     ctx.save();
1816:     ctx.strokeStyle = col;
1817:     ctx.lineWidth = 1.4;
1818:     ctx.beginPath();
1819:     ctx.arc(x, y, 9, 0, TAU);
1820:     ctx.stroke();
1821:     ctx.beginPath();
1822:     ctx.moveTo(x - 15, y);
1823:     ctx.lineTo(x - 5, y);
1824:     ctx.moveTo(x + 5, y);
1825:     ctx.lineTo(x + 15, y);
1826:     ctx.moveTo(x, y - 15);
1827:     ctx.lineTo(x, y - 5);
1828:     ctx.moveTo(x, y + 5);
1829:     ctx.lineTo(x, y + 15);
1830:     ctx.stroke();
1831:     ctx.fillStyle = col;
1832:     ctx.beginPath();
1833:     ctx.arc(x, y, 1.7, 0, TAU);
1834:     ctx.fill();
1835:     ctx.restore();
1836:   }
