1838:   drawMinimap(canvas, g) {
1839:     if (!canvas) return;
1840:     const ctx = canvas.getContext('2d');
1841:     const size = canvas.width;
1842:     const scale = size / g.world.size;
1843:     ctx.setTransform(1, 0, 0, 1, 0, 0);
1844:     ctx.clearRect(0, 0, size, size);
1845:     ctx.fillStyle = '#161a16';
1846:     ctx.fillRect(0, 0, size, size);
1847:     // roads
1848:     ctx.strokeStyle = 'rgba(90,88,76,0.5)';
1849:     ctx.lineWidth = 6 * scale * 6;
1850:     for (const x of g.world.roadsX) {
1851:       ctx.beginPath();
1852:       ctx.moveTo(x * scale, 0);
1853:       ctx.lineTo(x * scale, size);
1854:       ctx.stroke();
1855:     }
1856:     for (const y of g.world.roadsY) {
1857:       ctx.beginPath();
1858:       ctx.moveTo(0, y * scale);
1859:       ctx.lineTo(size, y * scale);
1860:       ctx.stroke();
1861:     }
1862:     // buildings
1863:     for (const b of g.world.buildings) {
1864:       const x = (b.x - b.w / 2) * scale;
1865:       const y = (b.y - b.h / 2) * scale;
1866:       ctx.fillStyle = 'rgba(96,92,78,0.45)';
1867:       ctx.fillRect(x, y, b.w * scale, b.h * scale);
1868:     }
1869:     // base
1870:     const bx = g.world.base.x * scale;
1871:     const by = g.world.base.y * scale;
1872:     ctx.fillStyle = 'rgba(255,175,80,0.14)';
1873:     ctx.beginPath();
1874:     ctx.arc(bx, by, 300 * scale, 0, TAU);
1875:     ctx.fill();
1876:     ctx.strokeStyle = 'rgba(255,190,110,0.55)';
1877:     ctx.lineWidth = 1.5;
1878:     ctx.beginPath();
1879:     ctx.arc(bx, by, 240 * scale, 0, TAU);
1880:     ctx.stroke();
1881:     // crates
1882:     for (const c of g.world.crates) {
1883:       if (c.opened) continue;
1884:       ctx.fillStyle = c.type === 'weapon' ? '#8ee9a0' : c.type === 'rare' ? '#78d9e0' : '#d9b46a';
1885:       ctx.fillRect(c.x * scale - 2, c.y * scale - 2, 4, 4);
1886:     }
1887:     if (g.supplyDrop) {
1888:       ctx.fillStyle = '#a6ff6e';
1889:       ctx.beginPath();
1890:       ctx.arc(g.supplyDrop.x * scale, g.supplyDrop.y * scale, 4, 0, TAU);
1891:       ctx.fill();
1892:       ctx.strokeStyle = 'rgba(166,255,110,0.6)';
1893:       ctx.beginPath();
1894:       ctx.arc(g.supplyDrop.x * scale, g.supplyDrop.y * scale, 8, 0, TAU);
1895:       ctx.stroke();
1896:     }
1897:     // enemies
1898:     for (const e of g.enemies) {
1899:       if (!e.alive) continue;
1900:       ctx.fillStyle = e.boss ? '#ff3b30' : '#e56b5a';
1901:       ctx.beginPath();
1902:       ctx.arc(e.x * scale, e.y * scale, e.boss ? 3.5 : 2, 0, TAU);
1903:       ctx.fill();
1904:     }
1905:     // allies
1906:     for (const s of g.soldiers) {
1907:       if (!s.alive) continue;
1908:       ctx.fillStyle = '#9ddc8a';
1909:       ctx.fillRect(s.x * scale - 1.5, s.y * scale - 1.5, 3, 3);
1910:     }
1911:     for (const s of g.structures) {
1912:       if (!s.alive) continue;
1913:       ctx.fillStyle = s.kind === 'turret' ? '#ffcf6a' : s.kind === 'lampbuild' ? '#ffe9a0' : '#7f8a7a';
1914:       ctx.fillRect(s.x * scale - 1.5, s.y * scale - 1.5, 3, 3);
1915:     }
1916:     // player
1917:     const px = g.player.x * scale;
1918:     const py = g.player.y * scale;
1919:     ctx.save();
1920:     ctx.translate(px, py);
1921:     ctx.rotate(g.player.facing);
1922:     ctx.fillStyle = '#ffe2a6';
1923:     ctx.beginPath();
1924:     ctx.moveTo(6, 0);
1925:     ctx.lineTo(-4, -4);
1926:     ctx.lineTo(-2, 0);
1927:     ctx.lineTo(-4, 4);
1928:     ctx.closePath();
1929:     ctx.fill();
1930:     ctx.restore();
1931:     ctx.strokeStyle = 'rgba(255,226,166,0.35)';
1932:     ctx.lineWidth = 1;
1933:     ctx.beginPath();
1934:     ctx.arc(px, py, 10, 0, TAU);
1935:     ctx.stroke();
1936:   }
1937: }
