/* Build */
#buildMenu { align-items: stretch; justify-content: flex-end; padding: 14px; background: linear-gradient(to left, rgba(3,5,4,.82), rgba(3,5,4,.05)); backdrop-filter: none; -webkit-backdrop-filter: none; }
#buildMenu .build-panel { align-self: center; width: min(470px, 100%); max-height: calc(100vh - 28px); padding: 20px 20px 16px; }
.build-grid { display: grid; grid-template-columns: 1fr; gap: 6px; }
.build-card {
  display: grid; grid-template-columns: 44px 1fr auto; gap: 10px; align-items: center;
  padding: 9px 10px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.018);
  cursor: pointer; transition: all .15s; text-align: left;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%);
}
.build-card:hover { border-color: rgba(243, 180, 95, 0.28); background: rgba(243, 180, 95, 0.045); }
.build-card.selected { border-color: rgba(243, 180, 95, 0.7); background: linear-gradient(100deg, rgba(94, 67, 31, 0.35), rgba(243, 180, 95, 0.03)); box-shadow: inset 2px 0 0 var(--amber); }
.build-card.unaffordable { opacity: .6; }
.bc-icon { width: 42px; height: 42px; display: grid; place-items: center; border: 1px solid var(--line); color: var(--amber); background: rgba(0,0,0,.2); }
.bc-icon svg { width: 26px; height: 26px; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }
.bc-body { min-width: 0; }
.bc-name { display: flex; align-items: baseline; gap: 6px; }
.bc-name b { font-family: var(--font-head); font-size: 15px; letter-spacing: .05em; color: #f0e7d4; font-weight: 600; }
.bc-name span { font-family: var(--font-head); font-size: 8px; letter-spacing: .08em; color: var(--dim); }
.bc-desc { font-size: 9px; color: var(--dim); line-height: 1.45; margin-top: 2px; }
.bc-cost { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 4px; }
.cost-chip { font-family: var(--font-head); font-size: 9px; letter-spacing: .03em; padding: 1px 5px; border: 1px solid rgba(255, 255, 255, 0.09); color: var(--muted); }
.cost-chip.bad { color: #ff8b7a; border-color: rgba(255, 92, 77, 0.3); }
.cost-chip.good { color: #cfe6b8; }
.bc-side { text-align: right; display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }
.bc-count { font-family: var(--font-head); font-size: 10px; color: var(--dim); letter-spacing: .04em; }
.bc-count b { color: var(--amber); }

